class ProjectManager {}
class Project {
  +startDate : date
  +endDate : date
}
abstract class WorkProduct {
  +description : string
  +percentComplete : float
}
class Requirement extends WorkProduct {}
class System extends WorkProduct {}
class User {
  +name : string
}
class Workshop {
  +date : date
}
class Test {
  +testResult : string
}
class Media {
  +type : string
}
class Platform {
  +name : string
}

ProjectManager "1" -- "*" Project : leads
Project "1" -- "*" Requirement : uses
Project "1" -- "0..1" System : produces
Requirement "1" -- "*" Workshop : validated in
User "1..*" -- "*" Workshop : participates in
System "1" -- "*" Test : validated by
Requirement "1" -- "*" Test : tested against
Requirement "1" -- "*" Media : published using
System "1" -- "*" Platform : deployed onto
@enduml

